def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    return float(v) if v is not None and math.isfinite(v) and v > 0 else 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x * r * r * r
            weight += x
    return float(4.0 * math.pi * total / (3.0 * weight * v)) if weight > 0 else 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and math.isfinite(z) and z >= 0:
            total += x * z
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    props = s.get('element_properties', {})
    data = {}
    weight = 0.0
    softness = 0.0
    numerator = 0.0
    for e, x in s.get('composition', {}).items():
        p = props.get(e, {})
        ie = p.get('first_ionization_energy_eV')
        ea = p.get('electron_affinity_eV')
        if x is not None and x > 0 and ie is not None and ea is not None:
            if math.isfinite(ie) and math.isfinite(ea) and ie - ea > 0.1:
                chi = 0.5 * (ie + ea)
                eta = ie - ea
                data[e] = (x, chi, eta)
                weight += x
                softness += x / eta
                numerator += x * chi / eta
    if weight <= 0 or softness <= 0:
        return 0.0
    center = numerator / softness
    value = sum(x * (chi - center) ** 2 / eta for x, chi, eta in data.values())
    return float(value / weight)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    occ = [max(0.0, site.get('occupancy', 1.0) or 0.0) for site in sites]
    total = sum(occ)
    if total <= 0:
        return 0.0
    minima = [math.inf] * n
    neighbors = s.get('neighbors', ())
    for nb in neighbors:
        i = nb['i']
        j = nb['j']
        d = nb.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and d > 0 and d < minima[i]:
            minima[i] = d
    coordination = [0.0] * n
    for nb in neighbors:
        i = nb['i']
        j = nb['j']
        d = nb.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and math.isfinite(minima[i]) and d <= 2.0 * minima[i]:
            coordination[i] += occ[j] * math.exp(1.0 - (d / minima[i]) ** 6)
    return float(sum(occ[i] * coordination[i] for i in range(n)) / total)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    props = s.get('element_properties', {})
    en = [props.get(site.get('element'), {}).get('eneg') for site in sites]
    radii = [props.get(site.get('element'), {}).get('covalent_radius_A') for site in sites]
    radii = [r if r is not None and math.isfinite(r) and r > 0 else 0.0 for r in radii]
    occ = [max(0.0, site.get('occupancy', 1.0) or 0.0) for site in sites]
    total = sum(occ)
    if total <= 0:
        return 0.0
    value = 0.0
    for nb in s.get('neighbors', ()):
        i = nb['i']
        j = nb['j']
        d = nb.get('distance_A')
        if 0 <= i < n and 0 <= j < n and sites[i].get('element') == sites[j].get('element'):
            if en[i] is not None and math.isfinite(en[i]) and en[i] >= 2.5 and radii[i] > 0 and radii[j] > 0 and d is not None and d > 0:
                ratio = d / (radii[i] + radii[j])
                if ratio <= 2.0:
                    value += occ[i] * occ[j] * math.exp(-(ratio ** 6))
    return float(value / (2.0 * total))
